interface Props {
  vuln: Vulnerability;
}

const VulnerabilityCard: React.FC<Props> = ({ vuln }) => {
  const [expanded, setExpanded] = useState(false);

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'Critical': return 'bg-red-500/10 text-red-400 border-red-500/50';
      case 'High': return 'bg-orange-500/10 text-orange-400 border-orange-500/50';
      case 'Medium': return 'bg-yellow-500/10 text-yellow-400 border-yellow-500/50';
      case 'Low': return 'bg-blue-500/10 text-blue-400 border-blue-500/50';
      default: return 'bg-slate-500/10 text-slate-400 border-slate-500/50';
    }
  };

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case 'Critical': return <AlertOctagon className="w-5 h-5" />;
      case 'High': return <AlertTriangle className="w-5 h-5" />;
      case 'Medium': return <Bug className="w-5 h-5" />;
      case 'Low': return <Info className="w-5 h-5" />;
      default: return <Info className="w-5 h-5" />;
    }
  };

  return (
    <div className="border border-slate-800 rounded-lg bg-slate-900/50 overflow-hidden mb-4 transition-all hover:border-slate-700">
      <div 
        className="p-4 flex items-center justify-between cursor-pointer"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-center gap-4">
          <div className={`p-2 rounded-md border ${getSeverityColor(vuln.severity)}`}>
            {getSeverityIcon(vuln.severity)}
          </div>
          <div>
            <div className="flex items-center gap-3">
              <h3 className="font-semibold text-slate-200 text-lg">{vuln.title}</h3>
              <span className={`text-xs px-2 py-0.5 rounded-full border ${getSeverityColor(vuln.severity)}`}>
                {vuln.severity}
              </span>
              {vuln.cwe && (
                <span className="text-xs text-slate-500 font-mono">
                  {vuln.cwe}
                </span>
              )}
            </div>
            <p className="text-sm text-slate-400 mt-1">
              Line {vuln.line}: {vuln.description.substring(0, 80)}{vuln.description.length > 80 ? '...' : ''}
